@Test
void createSessionCommandJournalIsAtomicDurableAndPayloadBound() throws Exception {
    var database = Files.createTempFile("ji-host-create-session-", ".db");
    ModelRef model = new ModelRef("profile", "model");
    try (HostStore store = store(database)) {
        HostStore.CreateSessionResult created = store.createSession(
                "create-1", "hash-a", "session-fixed", model, "workspace", NOW);
        assertTrue(created.firstApplication());
    }
    try (HostStore reopened = store(database)) {
        HostStore.CreateSessionResult retry = reopened.createSession(
                "create-1", "hash-a", "session-fixed", model, "workspace", NOW.plusSeconds(1));
        assertFalse(retry.firstApplication());
        assertEquals("session-fixed", retry.sessionId());
        var conflict = assertThrows(io.github.diodeme.ji.error.JiException.class,
                () -> reopened.createSession("create-1", "hash-b", "session-fixed",
                        model, "workspace", NOW));
        assertEquals(io.github.diodeme.ji.error.ErrorCode.COMMAND_PAYLOAD_CONFLICT,
                conflict.error().code());
        assertEquals(1, reopened.list().size());
    }
}

